    "diastolic_blood_pressure_right_brachial_measurement_1"  DOUBLE PRECISION,  -- SDTM VS.DIABP | LOINC:8462-4 | [mm[Hg]]
    "diastolic_blood_pressure_right_brachial_measurement_2"  DOUBLE PRECISION,  -- SDTM VS.DIABP | LOINC:8462-4 | [mm[Hg]]
    "diastolic_blood_pressure_right_brachial_measurement_3"  DOUBLE PRECISION,  -- SDTM VS.DIABP | LOINC:8462-4 | [mm[Hg]]
    "heart_rate"  DOUBLE PRECISION,  -- SDTM VS.HR | LOINC:8867-4 | [/min]
    "height_in_cm"  DOUBLE PRECISION,  -- SDTM VS.HEIGHT | LOINC:8302-2 | [cm]
    "hip_circumference_in_cm"  DOUBLE PRECISION,  -- SDTM VS.HIPCIR | LOINC:62409-8 | [cm]
