    "left_anterior_tibial_pressure"  DOUBLE PRECISION,  -- SDTM VS.LATP | [mm[Hg]]
    "left_posterior_tibial_abi"  DOUBLE PRECISION,  -- SDTM VS.LTABI | LOINC:8641-0 | [1]
    "left_posterior_tibial_pressure"  DOUBLE PRECISION,  -- SDTM VS.LPTP | [mm[Hg]]
    "right_anterior_tibial_abi"  DOUBLE PRECISION,  -- SDTM VS.RABIAT | LOINC:37399-3 | [1]
    "right_anterior_tibial_pressure"  DOUBLE PRECISION,  -- SDTM VS.RATP | [mm[Hg]]
    "right_posterior_tibial_abi"  DOUBLE PRECISION,  -- SDTM VS.RABIAT | LOINC:37399-3 | [1]
    "right_posterior_tibial_pressure"  DOUBLE PRECISION,  -- SDTM VS.RPTP | [mm[Hg]]
    "systolic_blood_pressure_right_brachial_measurement_1"  DOUBLE PRECISION,  -- SDTM VS.SYSBP | LOINC:8480-6 | [mm[Hg]]
    "systolic_blood_pressure_right_brachial_measurement_2"  DOUBLE PRECISION,  -- SDTM VS.SYSBP | LOINC:8480-6 | [mm[Hg]]
    "systolic_blood_pressure_right_brachial_measurement_3"  DOUBLE PRECISION,  -- SDTM VS.SYSBP | LOINC:8480-6 | [mm[Hg]]
