-- ============================================================
-- EHVol full-width standardized table
-- ============================================================
DROP TABLE IF EXISTS ehvol_participants CASCADE;
CREATE TABLE IF NOT EXISTS ehvol_participants (
    _ingest_id       BIGSERIAL,
    _source_dataset  TEXT DEFAULT 'EHVol',
    _ingested_at     TIMESTAMPTZ DEFAULT NOW(),
    _data_quality_score DOUBLE PRECISION,
    _source_raw_json JSONB,
    -- ── Standardized columns ──
    -- ── CM ──────────────────────────────────
    "diabetes_therapy"  VARCHAR(100),  -- SDTM CM.CMCAT
    "name"  VARCHAR(200),  -- SDTM CM.CMTRT
    "name_1"  VARCHAR(200),  -- SDTM CM.CMTRT
    -- ── DM ──────────────────────────────────
    "address"  VARCHAR(100),  -- SDTM DM.SITEID
    "age"  INTEGER,  -- SDTM DM.AGE | LOINC:30525-0 | [a]
    "are_you_one_of_a_twin_or_triplet"  BOOLEAN,  -- SDTM DM.TWIN
    "city_of_residence_during_childhood"  VARCHAR(100),  -- SDTM DM.CHLDCITY
    "consanguinous_marriage"  BOOLEAN,  -- SDTM DM.CONSANG
    "current_city_of_residence"  VARCHAR(100),  -- SDTM DM.SITEID
    "dna_id"  VARCHAR(50),  -- SDTM DM.USUBJID
    "date_of_birth"  DATE,  -- SDTM DM.BRTHDTC | LOINC:21112-8
    "date_of_enrolment"  DATE,  -- SDTM DM.RFICDTC
    "gender"  VARCHAR(10),  -- SDTM DM.SEX | LOINC:46098-0
    "how_many_siblings_you_have"  INTEGER,  -- SDTM DM.NSIBLING
    "marital_status"  VARCHAR(50),  -- SDTM DM.MARSTATS
    "nationality"  VARCHAR(50),  -- SDTM DM.COUNTRY
    "number_of_children"  INTEGER,  -- SDTM DM.NCHILD
    "number_of_wives"  INTEGER,  -- SDTM DM.NWIVES
    -- ── EG ──────────────────────────────────
    "ecg_conclusion"  TEXT,  -- SDTM EG.EGSTRESC
    "p_wave_abnormality"  VARCHAR(100),  -- SDTM EG.EGPWAVE | LOINC:8625-3
    "pr_interval"  DOUBLE PRECISION,  -- SDTM EG.PR | LOINC:8625-6 | [ms]
    "qrs_abnormalities"  VARCHAR(200),  -- SDTM EG.EGQRS | LOINC:8633-7
    "qrs_duration"  DOUBLE PRECISION,  -- SDTM EG.QRSDUR | LOINC:8625-6 | [ms]
    "qtc_interval"  DOUBLE PRECISION,  -- SDTM EG.QTC | LOINC:8636-3 | [ms]
    "rate"  DOUBLE PRECISION,  -- SDTM EG.EGRATE | LOINC:8867-4 | [/min]
    "regularity"  VARCHAR(50),  -- SDTM EG.EGREG
    "rhythm"  VARCHAR(100),  -- SDTM EG.RHYTHM
    "st_segment_abnormalities"  VARCHAR(200),  -- SDTM EG.EGSTWAVE | LOINC:8625-3
    "t_wave_abnormalities"  VARCHAR(200),  -- SDTM EG.EGTWAVE | LOINC:8625-3
    -- ── FA ──────────────────────────────────
    "aortic_regurge"  VARCHAR(50),  -- SDTM FA.AR
    "aortic_root"  DOUBLE PRECISION,  -- SDTM FA.AORTROOT | LOINC:18028-2 | [mm]
    "aortic_stenosis"  VARCHAR(50),  -- SDTM FA.AS
    "ef"  DOUBLE PRECISION,  -- SDTM FA.EF | LOINC:18052-2 | [%]
    "echo_date"  DATE,  -- SDTM FA.FADTC
    "fs"  DOUBLE PRECISION,  -- SDTM FA.LVFS | LOINC:18049-8 | [%]
    "ivsd"  DOUBLE PRECISION,  -- SDTM FA.IVSD | LOINC:18087-8 | [mm]
    "ivss"  DOUBLE PRECISION,  -- SDTM FA.IVSSYS | LOINC:29430-6 | [mm]
    "lvedd"  DOUBLE PRECISION,  -- SDTM FA.LVEDD | LOINC:18026-6 | [mm]
    "lvesd"  DOUBLE PRECISION,  -- SDTM FA.LVESD | LOINC:18150-4 | [mm]
    "lvm"  DOUBLE PRECISION,  -- SDTM FA.LVM | LOINC:18086-0 | [g]
    "lvpws"  DOUBLE PRECISION,  -- SDTM FA.LVPWSYST | LOINC:29430-6 | [mm]
    "left_atrium"  DOUBLE PRECISION,  -- SDTM FA.LADIAM | LOINC:18035-7 | [mm]
    "left_ventricular_ef"  DOUBLE PRECISION,  -- SDTM FA.EF | LOINC:18052-2 | [%]
    "left_ventricular_ejection_fraction"  DOUBLE PRECISION,  -- SDTM FA.LVEF | LOINC:18052-2 | [%]
    "left_ventricular_end_diastolic_volume"  DOUBLE PRECISION,  -- SDTM FA.LVEDV | LOINC:18026-6 | [mL]
    "left_ventricular_end_systolic_volume"  DOUBLE PRECISION,  -- SDTM FA.LVESV | LOINC:18150-4 | [mL]
    "left_ventricular_mass"  DOUBLE PRECISION,  -- SDTM FA.LVM | LOINC:18086-0 | [g]
    "mri"  TEXT,  -- SDTM FA.MRI
    "mri_date"  DATE,  -- SDTM FA.MRIDTC
    "mitral_regurge"  VARCHAR(50),  -- SDTM FA.MR
    "mitral_stenosis"  VARCHAR(50),  -- SDTM FA.MS
    "other_mri_findings"  TEXT,  -- SDTM FA.FAOTHER
    "pulmonary_stenosis"  VARCHAR(50),  -- SDTM FA.PS
    "right_ventricle"  DOUBLE PRECISION,  -- SDTM FA.RVDIAM | LOINC:18015-9 | [mm]
    "right_ventricular_ef"  DOUBLE PRECISION,  -- SDTM FA.RVEF | LOINC:10230-1 | [%]
    "s1"  VARCHAR(50),  -- SDTM FA.FACLIN
    "s2"  VARCHAR(50),  -- SDTM FA.FACLIN
    "s3"  BOOLEAN,  -- SDTM FA.S3SOUND | LOINC:48451-8
    "s4"  BOOLEAN,  -- SDTM FA.S4SOUND | LOINC:48452-6
    "subaortic_membrane"  BOOLEAN,  -- SDTM FA.SUBAORT
    "tricuspid_regurge"  VARCHAR(50),  -- SDTM FA.TR
    "tricuspid_stenosis"  VARCHAR(50),  -- SDTM FA.TS
    -- ── IE ──────────────────────────────────
    "are_your_parents_grandparents_or_great_grandparents_from_non_eg"  BOOLEAN,  -- SDTM IE.IESPCAT
    "communication_difficulties"  BOOLEAN,  -- SDTM IE.IESPCAT
    "contraindications_for_mri"  BOOLEAN,  -- SDTM IE.IESPCAT
    "is_there_any_chance_you_might_be_pregnant"  BOOLEAN,  -- SDTM IE.IESPCAT
    "known_cvs_disease"  BOOLEAN,  -- SDTM IE.IESPCAT
    "known_collagen_disease"  BOOLEAN,  -- SDTM IE.IESPCAT
    "non_egyptian_parents"  BOOLEAN,  -- SDTM IE.IESPCAT
    "pregnant_female"  BOOLEAN,  -- SDTM IE.IESPCAT
    "unwilling_to_participate"  BOOLEAN,  -- SDTM IE.IESPCAT
    "volunteer_under_18_year_old"  BOOLEAN,  -- SDTM IE.IESPCAT
    -- ── LB ──────────────────────────────────
    "hba1c"  DOUBLE PRECISION,  -- SDTM LB.HBA1C | LOINC:4548-4 | [%]
    "troponin_i"  DOUBLE PRECISION,  -- SDTM LB.TRPI | LOINC:42757-5 | [ng/mL]
    -- ── MH ──────────────────────────────────
    "anaemia"  BOOLEAN,  -- SDTM MH.MHTERM
    "autoimmune_problems"  BOOLEAN,  -- SDTM MH.MHTERM
    "do_you_drink_alcohol"  BOOLEAN,  -- SDTM MH.MHTERM
    "do_you_take_any_medication_currently"  BOOLEAN,  -- SDTM MH.MHTERM
    "do_you_wish_to_be_informed_if_we_discover_any_abnormality_was_d"  BOOLEAN,  -- SDTM MH.MHTERM
    "have_you_undergone_an_operation_or_any_surgical_procedures"  BOOLEAN,  -- SDTM MH.MHTERM
    "heart_attack_or_angina"  BOOLEAN,  -- SDTM MH.MHTERM
    "history_of_sudden_death_history"  BOOLEAN,  -- SDTM MH.MHTERM
    "kidney_problems"  BOOLEAN,  -- SDTM MH.MHTERM
    "liver_problems"  BOOLEAN,  -- SDTM MH.MHTERM
    "lung_problems"  BOOLEAN,  -- SDTM MH.MHTERM
    "malignancy"  BOOLEAN,  -- SDTM MH.MHTERM
    "muscloskeletal_problems"  BOOLEAN,  -- SDTM MH.MHTERM
    "neurological_problems"  BOOLEAN,  -- SDTM MH.MHTERM
    "rheumatic_fever"  BOOLEAN,  -- SDTM MH.MHTERM
    -- ── SC ──────────────────────────────────
    "abnormal_physical_structure"  BOOLEAN,  -- SDTM SC.SCPHYDEF
    "parents_occupation"  VARCHAR(200),  -- SDTM SC.SCTEST
    -- ── SU ──────────────────────────────────
    "how_long_have_you_been_smoking"  DOUBLE PRECISION,  -- SDTM SU.ENDUR
    "how_many_cigarettes_have_you_been_smoking_a_day_before_you_quit"  INTEGER,  -- SDTM SU.SUCAT
    "how_many_cigarettes_have_you_been_smoking_a_day"  INTEGER,  -- SDTM SU.SUCAT
    "how_many_years_have_you_been_smoking"  DOUBLE PRECISION,  -- SDTM SU.ENDUR
    -- ── SV ──────────────────────────────────
    "consent_scan"  TEXT,  -- SDTM SV.ADMIN
    "consent_obtained"  TEXT,  -- SDTM SV.ADMIN
    "amount_of_alcohol"  TEXT,  -- SDTM SV.ADMIN
    "complete"  BOOLEAN,  -- SDTM SV.SVCOMP
    "complete_1"  BOOLEAN,  -- SDTM SV.SVCOMP
    "complete_2"  BOOLEAN,  -- SDTM SV.SVCOMP
    "complete_3"  BOOLEAN,  -- SDTM SV.SVCOMP
    "complete_4"  BOOLEAN,  -- SDTM SV.SVCOMP
    "complete_5"  BOOLEAN,  -- SDTM SV.SVCOMP
    "complete_6"  BOOLEAN,  -- SDTM SV.SVCOMP
    "complete_7"  BOOLEAN,  -- SDTM SV.SVCOMP
    "complete_8"  BOOLEAN,  -- SDTM SV.SVCOMP
    "complete_9"  BOOLEAN,  -- SDTM SV.SVCOMP
    "current_recent_smoker_1_year"  TEXT,
    "diabetes_mellitus"  TEXT,
    "do_any_of_your_own_children_parents_or_siblings_have_any_of_the"  BOOLEAN,
    "do_any_of_your_own_children_parents_or_siblings_have_any_of_t_2"  BOOLEAN,
    "do_any_of_your_own_children_parents_or_siblings_have_any_of_t_3"  BOOLEAN,
    "do_any_of_your_own_children_parents_or_siblings_have_any_of_t_4"  BOOLEAN,
    "do_any_of_your_own_children_parents_or_siblings_have_any_of_t_5"  BOOLEAN,
    "does_any_other_non_cardiac_condition_run_in_your_family"  TEXT,  -- SDTM SV.ADMIN
    "dyslipidemia"  TEXT,
    "email"  TEXT,  -- SDTM SV.ADMIN
    "examination_date"  DATE,  -- SDTM SV.SVSTDTC
    "father_s_city_of_origin"  TEXT,
    "father_s_city_of_origin_1"  TEXT,
    "from_where"  TEXT,  -- SDTM SV.ADMIN
    "high_blood_pressure"  TEXT,
    "history_of_familial_cardiomyopathies"  BOOLEAN,
    "history_of_premature_cad"  BOOLEAN,
    "home_tel"  VARCHAR(50),  -- SDTM SV.ADMIN
    "home_tel_2"  VARCHAR(50),  -- SDTM SV.ADMIN
    "lvpwd"  DOUBLE PRECISION,  -- LOINC:29430-6 | [mm]
    "list_these_medications"  TEXT,  -- SDTM SV.ADMIN
    "malignancy_details"  TEXT,  -- SDTM SV.ADMIN
    "mobile_tel"  VARCHAR(50),  -- SDTM SV.ADMIN
    "mobile_tel_2"  VARCHAR(50),  -- SDTM SV.ADMIN
    "notes"  TEXT,  -- SDTM SV.ADMIN
    "offspring_of_consanguinous_marriage"  TEXT,
    "other"  TEXT,  -- SDTM SV.ADMIN
    "other_findings"  TEXT,  -- SDTM SV.ADMIN
    "physical_abnormality_details"  TEXT,  -- SDTM SV.ADMIN
    "prior_heart_failure_previous_hx"  TEXT,
    "procedure_details"  TEXT,  -- SDTM SV.ADMIN
    "pulmonary_regurge"  VARCHAR(50),
    "record_id"  TEXT,
    "specifiy_p_wave_abnormality"  TEXT,  -- SDTM SV.ADMIN
    "specifiy_qrs_abnormality"  TEXT,  -- SDTM SV.ADMIN
    "specifiy_st_seg_abnormality"  TEXT,  -- SDTM SV.ADMIN
    "specifiy_t_wave_abnormality"  TEXT,  -- SDTM SV.ADMIN
    "type"  TEXT,  -- SDTM SV.ADMIN
    "we_may_contact_you_yearly_to_follow_up_on_your_health_do_you_ac"  TEXT,  -- SDTM SV.ADMIN
    "what_is_this_these_condition_s"  TEXT,  -- SDTM SV.ADMIN
    "where_did_you_spend_your_childhood"  TEXT,  -- SDTM SV.ADMIN
    "who_and_what_disease"  TEXT,  -- SDTM SV.ADMIN
    -- ── VS ──────────────────────────────────
    "bmi"  DOUBLE PRECISION,  -- SDTM VS.BMI | LOINC:39156-5 | [kg/m2]
    "bp"  DOUBLE PRECISION,  -- SDTM VS.DIABP | LOINC:8462-4 | [mm[Hg]]
    "bsa"  DOUBLE PRECISION,  -- SDTM VS.BSA | LOINC:3140-1 | [m2]
    "fat_mass"  DOUBLE PRECISION,  -- SDTM VS.FATMASS | LOINC:73708-0 | [kg]
    "fat_free_mass"  DOUBLE PRECISION,  -- SDTM VS.LEANMASS | [kg]
    "heart_rate"  DOUBLE PRECISION,  -- SDTM VS.HR | LOINC:8867-4 | [/min]
    "heart_rate_during_mri"  DOUBLE PRECISION,  -- SDTM VS.HR | LOINC:8867-4 | [/min]
    "height_cm"  DOUBLE PRECISION,  -- SDTM VS.HEIGHT | LOINC:8302-2 | [cm]
    "jvp"  VARCHAR(50),  -- SDTM VS.JVP
    "span_cm"  DOUBLE PRECISION,  -- SDTM VS.ARMSPAN | [cm]
    "weight_kg"  DOUBLE PRECISION,  -- SDTM VS.WEIGHT | LOINC:29463-7 | [kg]
    CONSTRAINT ehvol_participants_pkey PRIMARY KEY (_ingest_id)
);
CREATE INDEX IF NOT EXISTS ehvol_participants_dataset_idx ON ehvol_participants(_source_dataset);
CREATE INDEX IF NOT EXISTS ehvol_participants_ingest_idx  ON ehvol_participants(_ingested_at);
CREATE UNIQUE INDEX IF NOT EXISTS ehvol_participants_dna_id_uidx ON ehvol_participants(dna_id) WHERE dna_id IS NOT NULL;

-- ============================================================
-- Core cross-dataset view (common columns from BHS + EHVol)
-- Wide clinical columns live in bhs_participants / ehvol_participants;
-- this view provides a minimal cross-study summary.
-- ============================================================
CREATE OR REPLACE VIEW core_participants AS
SELECT
    _ingest_id::TEXT                 AS participant_id,
    _source_dataset                  AS source_dataset,
    "age_at_enrollment"              AS age,
    "enrollment_date"                AS enrollment_date,
    "hba1c"                          AS hba1c,
    "heart_rate"                     AS heart_rate,
    _data_quality_score              AS data_quality_score,
    _ingested_at                     AS ingested_at
FROM bhs_participants
UNION ALL
SELECT
    _ingest_id::TEXT                 AS participant_id,
    _source_dataset                  AS source_dataset,
    "age"                            AS age,
    "date_of_enrolment"              AS enrollment_date,
    NULL::DOUBLE PRECISION           AS hba1c,
    "heart_rate"                     AS heart_rate,
    _data_quality_score              AS data_quality_score,
    _ingested_at                     AS ingested_at
FROM ehvol_participants;

